import{_ as o,l as i,o as e,c as n,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"扫描线","description":"","frontmatter":{"title":"扫描线","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sweep-line.md","filePath":"cs/sweep-line.md","lastUpdated":1789023840000}'),c={name:"cs/sweep-line.md"};function _(m,a,B,u,E,f){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="扫描线" tabindex="-1">扫描线 <a class="header-anchor" href="#扫描线" aria-label="Permalink to &quot;扫描线&quot;">​</a></h1><div class="epigraph"><p>竖线从左扫到右，在事件点更新有序结构；矩形面积并、交点、天际线都变成动态一维问题。</p><footer>—— 据 Bentley and Wood, 1980；CLRS 第 33 章扫描思想整理</footer></div><p>上一课<a href="/cs/rotating-calipers">旋转卡壳</a>在凸包上转。扫描线是另一范式：按 \\(x\\) 排序事件，维护与扫描线相交的状态。缺口是这套事件 + 平衡树/线段树。不重写凸包。后课最近点对也用分治或扫描。线段交 Bentley–Ottmann 后专课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>矩形并面积：左右边事件，扫描线上按 \\(y\\) 的覆盖次数线段树，每个 \\(\\Delta x\\) 乘当前覆盖长度。天际线、周长类似。扫描线与 \\(x\\) 轴平行的假设：只在事件处拓扑变。</p><p>缺口是离散化 \\(y\\) + 区间覆盖，不是卡壳。</p><h3 id="不是平面扫描的全部" tabindex="-1">不是平面扫描的全部 <a class="header-anchor" href="#不是平面扫描的全部" aria-label="Permalink to &quot;不是平面扫描的全部&quot;">​</a></h3><p>线段求交要处理交点也当事件（下一课的下一课）。本课先矩形、水平/竖直。斜线段要更完整的事件队列。</p><p><span class="marginnote">Bentley–Wood 矩形并。扫描线是计算几何标准。后课 Bentley–Ottmann 交点事件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>事件排序。结构：多重集合、线段树、平衡树。惰性标记覆盖。离散坐标。</p>',11)),(e(),s(h,null,{default:r(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EV%5B%22%E6%8C%89%20x%20%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20ST%5B%22%E6%89%AB%E6%8F%8F%E7%BA%BF%E4%B8%8A%E7%BB%93%E6%9E%84%22%5D%0A%20%20ST%20--%3E%20ANS%5B%22%E9%9D%A2%E7%A7%AF%20%2F%20%E5%B9%B6%20%2F%20%E5%A4%A9%E9%99%85%E7%BA%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>同一 \\(x\\) 先入后出要定序。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>平移不变：两事件之间状态常数。把二维变一维动态。与扫描线做凸包（Graham 不是扫描线主形态）。与平面图平面扫描点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 BO 交点。三维扫描不写。后课默认：矩形并/覆盖用扫描线 + 线段树。下一课最近点对。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件排序 + 线上动态结构。</li><li>矩形并是标准实例。</li><li>交点当事件留给 BO。</li><li>出处：Bentley and Wood, 1980；CLRS 第 33 章。</li></ul>',7))])}const T=o(c,[["render",_]]);export{x as __pageData,T as default};
